<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\UserGrantedClientScopes;

final class UserGrantedClientScopesUnitTest extends TestCase
{
    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new UserGrantedClientScopes(
            uid: 'one',
            user: new UserRef('one'),
            trustedClient: new TrustedClientRef('one'),
            scope: 'one',
            granted: true,
            decisionAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->build();
        $calculated = UserGrantedClientScopes::calculatedFields();

        // @Assert
        $this->assertEquals([], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged());
        $this->assertEquals($one->getTrustedClient(), $other->getTrustedClient());
        $this->assertTrue($one->isTrustedClientChanged());
        $this->assertEquals($one->getScope(), $other->getScope());
        $this->assertTrue($one->isScopeChanged());
        $this->assertEquals($one->isGranted(), $other->isGranted());
        $this->assertTrue($one->isGrantedChanged());
        $this->assertEquals($one->getDecisionAt(), $other->getDecisionAt());
        $this->assertTrue($one->isDecisionAtChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
    {
        // @Arrange
        $base = new UserGrantedClientScopes(
            uid: 'one',
            user: new UserRef('one'),
            trustedClient: new TrustedClientRef('one'),
            scope: 'one',
            granted: true,
            decisionAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );
        $other = new UserGrantedClientScopes(
            uid: 'other',
            user: new UserRef('other'),
            trustedClient: new TrustedClientRef('other'),
            scope: 'other',
            granted: false,
            decisionAt: (new \DateTimeImmutable('1981-09-06T14:32:45.123Z')),
            version: 2,
        );

        // @Act
        $one = $base->replace($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged($base));
        $this->assertEquals($one->getTrustedClient(), $other->getTrustedClient());
        $this->assertTrue($one->isTrustedClientChanged($base));
        $this->assertEquals($one->getScope(), $other->getScope());
        $this->assertTrue($one->isScopeChanged($base));
        $this->assertEquals($one->isGranted(), $other->isGranted());
        $this->assertTrue($one->isGrantedChanged($base));
        $this->assertEquals($one->getDecisionAt(), $other->getDecisionAt());
        $this->assertTrue($one->isDecisionAtChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
    }
    public function test_json_compare(): void
    {
        // @Arrange
        $one = new UserGrantedClientScopes(
            uid: 'one',
            user: new UserRef('one'),
            trustedClient: new TrustedClientRef('one'),
            scope: 'one',
            granted: true,
            decisionAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['user']['$ref']);
        $this->assertEquals('one', $json['trustedClient']['$ref']);
        $this->assertEquals('one', $json['scope']);
        $this->assertEquals(true, $json['granted']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['decisionAt']);
        $this->assertEquals(1, $json['version']);
    }
    public function test_create_store_values(): void
    {
        // @Arrange
        $one = new UserGrantedClientScopes(
            uid: 'one',
            user: new UserRef('one'),
            trustedClient: new TrustedClientRef('one'),
            scope: 'one',
            granted: true,
            decisionAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $other = UserGrantedClientScopes::create($one->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged());
        $this->assertEquals($one->getTrustedClient(), $other->getTrustedClient());
        $this->assertTrue($one->isTrustedClientChanged());
        $this->assertEquals($one->getScope(), $other->getScope());
        $this->assertTrue($one->isScopeChanged());
        $this->assertEquals($one->isGranted(), $other->isGranted());
        $this->assertTrue($one->isGrantedChanged());
        $this->assertEquals($one->getDecisionAt(), $other->getDecisionAt());
        $this->assertTrue($one->isDecisionAtChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
        $this->assertCount(0, $one->getTheEvents());
        $this->assertCount(1, $other->getTheEvents());
    }
    public function test_update_change_values(): void
    {
        $base = new UserGrantedClientScopes(
            uid: 'one',
            user: new UserRef('one'),
            trustedClient: new TrustedClientRef('one'),
            scope: 'one',
            granted: true,
            decisionAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );
        $other = new UserGrantedClientScopes(
            uid: 'other',
            user: new UserRef('other'),
            trustedClient: new TrustedClientRef('other'),
            scope: 'other',
            granted: false,
            decisionAt: (new \DateTimeImmutable('1981-09-06T14:32:45.123Z')),
            version: 2,
        );

        // @Act
        $one = $base->update($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged($base));
        $this->assertEquals($one->getTrustedClient(), $other->getTrustedClient());
        $this->assertTrue($one->isTrustedClientChanged($base));
        $this->assertEquals($one->getScope(), $other->getScope());
        $this->assertTrue($one->isScopeChanged($base));
        $this->assertEquals($one->isGranted(), $other->isGranted());
        $this->assertTrue($one->isGrantedChanged($base));
        $this->assertEquals($one->getDecisionAt(), $other->getDecisionAt());
        $this->assertTrue($one->isDecisionAtChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
        $this->assertCount(0, $other->getTheEvents());
        $this->assertCount(1, $one->getTheEvents());
    }
